export type Game = { roundDeck:DeckSnapshot; aiAutoCloseAt:number|null; public: Public; players: Map<C.PlayerId,Player>; tiles: Map<C.TileId,C.Tile>; wall: C.TileId[]; cursor: number; response: Response|null; review: Review|null; receipts: Map<string,{hash:string;result:C.CommandResult}>; restoreReceipts:Map<string,{hash:string;proofHash:string;playerId:C.PlayerId;sessionId:string}>; settlements: Set<string>; archive: C.PublicRoomSnapshot[]; rng: number; serial: number; processGeneration: string; pausedRemaining: number|null; expiresAt: number|null; pendingWithdrawal: boolean; firstRecoveryPending:boolean; botDue: { playerId: C.PlayerId; epoch:number; phaseId:C.PhaseId; at:number }|null; pendingJobs: C.ServerOnly.TimerJob[]; lastAutoDiscard: {playerId:C.PlayerId;at:number;reason:'TIMEOUT'|'BOT'}|null };
