function automatic(p:C.PublicPlayer){return p.presence==='BOT'||(p.autoPlay===true&&p.presence==='HUMAN'&&p.connected);}
function usesAiReview(g:Game){return ['1.2.0','1.3.0','1.4.0','1.4.1','1.5.0','1.5.1','1.6.0'].includes(g.public.rulesVersion);}
