function enterTurn(g:Game,pid:C.PlayerId,now:number,eat:boolean,mustDiscard:boolean){phase(g,{kind:'TURN_ACTION',actorId:pid,mustDiscard,isEatTurn:eat},now,mustDiscard?timingForRules(g.public.rulesVersion).postHuDiscardMs:timingForRules(g.public.rulesVersion).turnMs);scheduleBot(g,now);}
