function closeResponse(g:Game,now:number){const r=g.response!;if(r.frozen)return;r.frozen=true;const ds=person(g,r.discarderId).seat;r.queue=[...r.intents].filter(([,intent])=>intent==='HU').map(([pid])=>pid).sort((a,b)=>((person(g,a).seat-ds+g.public.capacity)%g.public.capacity)-((person(g,b).seat-ds+g.public.capacity)%g.public.capacity));r.eater=[...r.intents].find(([,intent])=>intent==='EAT')?.[0]??null;continueResponse(g,now);}
