 while(r.queue.length){const pid=r.queue.shift()!,pub=person(g,pid);if(pub.presence==='BOT')continue;const source=sourceFor(g,pid);const ids=[...g.players.get(pid)!.draft.orderedTileIds,source.borrowedTileId] as unknown as C.Fourteen<C.TileId>;phase(g,{kind:'HU_COMPOSE',applicantId:pid,source},now,timingForRules(g.public.rulesVersion).composeMs);g.players.get(pid)!.candidateDraft={phaseId:g.public.phase.phaseId,source,candidateDraftVersion:1 as C.DraftVersion,sentence:{orderedTileIds:ids,commaAfterTileIds:g.players.get(pid)!.draft.commaAfterTileIds}};g.public.discards.find(d=>d.discardId===r.discardId)!.status='RESERVED';if(pub.presence==='DISCONNECTED_GRACE')pauseClaimant(g,pid,now);return;}
 const d=g.public.discards.find(d=>d.discardId===r.discardId)!;d.status='AVAILABLE';if(r.eater){const pub=person(g,r.eater);if(pub.connected&&pub.presence==='HUMAN'&&(g.public.rulesVersion==='1.6.0'||pub.eatCount<3)){const p=g.players.get(pub.playerId)!;p.hand.push(d.tile.tileId);p.protected=d.tile.tileId;pub.eatCount++;d.status='CLAIMED';normalize(g,pub.playerId);g.response=null;enterTurn(g,pub.playerId,now,true,false);return;}}
