function freezeDeadline(g:Game,now:number){for(const p of g.players.values())if(p.manualTurnDeadline?.phaseId===g.public.phase.phaseId&&p.manualTurnDeadline.remainingMs===undefined)p.manualTurnDeadline.remainingMs=Math.max(0,p.manualTurnDeadline.endsAt-now);if(g.pausedRemaining===null&&g.public.phase.deadline)g.pausedRemaining=Math.max(0,g.public.phase.deadline.endsAt-now);if(g.public.phase.deadline)g.public.phase.deadline.remainingMsWhenPaused=g.pausedRemaining;g.botDue=null;}
