export function disconnect(g:Game,pid:C.PlayerId,session:string,now:number){const p=g.players.get(pid);if(!p||p.sessionId!==session||p.seat===null||g.public.phase.kind==='ROOM_CLOSED')return;const pub=person(g,pid);if(!pub.connected)return;pub.connected=false;pub.presence='DISCONNECTED_GRACE';if(g.botDue?.playerId===pid)g.botDue=null;pub.graceEndsAt=(now+rules.disconnectGraceMs) as C.UtcMs;if(!online(g).length){freezeDeadline(g,now);g.expiresAt??=now+rules.allOfflineRetentionMs;g.public.suspension={kind:'PAUSED_ALL_OFFLINE',expiresAt:g.expiresAt as C.UtcMs};}else if(applicant(g)===pid)pauseClaimant(g,pid,now);bump(g);refreshJobs(g,now);}
